<template>
  <div class="equipment-type-container">
    <!-- 查询区域 -->
    <el-row>
      <el-col :span="18">
        <el-form :inline="true" :model="queryForm" class="query-form">
          <el-form-item label="设备名称">
            <el-input
              v-model="queryForm.deviceName"
              placeholder="请设备名称"
            ></el-input>
          </el-form-item>
          <el-form-item label="设备型号">
            <el-input
              v-model="queryForm.deviceModel"
              placeholder="请输入设备型号"
            ></el-input>
          </el-form-item>
          <el-form-item label="设备分类">
            <el-cascader
              placeholder="请选择分类名称"
              :options="categoryList"
              v-model="selectedCategory"
              :props="{ checkStrictly: true }"
              clearable
              filterable>
            </el-cascader>
          </el-form-item>
          <el-form-item label="录入日期">
            <el-date-picker
              v-model="queryForm.beginTime"
              type="date"
              placeholder="开始日期"
              value-format="yyyy-MM-dd"
            ></el-date-picker>
            <span style="margin: 0 5px">至</span>
            <el-date-picker
              v-model="queryForm.endTime"
              type="date"
              placeholder="结束日期"
              value-format="yyyy-MM-dd"
            ></el-date-picker>
          </el-form-item>
          <el-form-item label="设备入录员">
            <el-input
              v-model="queryForm.deviceCreateUser"
              placeholder="请输入设备录入员"
            ></el-input>
          </el-form-item>
        </el-form>
      </el-col>
      <el-col :span="6">
        <el-form inline style="text-align: right">
          <el-form-item>
            <el-button type="primary" @click="handleQuery">查询</el-button>
          </el-form-item>
          <el-form-item>
            <el-button @click="handleReset">重置</el-button>
          </el-form-item>
          <el-form-item>
            <el-button type="success" @click="handleAdd('add')">新增</el-button>
          </el-form-item></el-form
        >
      </el-col>
    </el-row>

    <!-- 表格区域 -->
    <el-table
      :data="tableData"
      border
      style="width: 100%; margin-top: 20px"
      row-key="id"
      :tree-props="{ children: 'children', hasChildren: 'hasChildren' }"
      stripe
    >
      >
      <el-table-column type="index"></el-table-column>
      <el-table-column prop="deviceCode" label="设备编码" align="center"></el-table-column>
      <el-table-column prop="deviceName" label="设备名称" align="center"></el-table-column>
      <el-table-column  label="设备分类" align="center">
        <template slot-scope="scope">
          {{ getCategoryName(scope.row.parentId,scope.row.childId)}}
        </template>
      </el-table-column>
      <el-table-column prop="deviceDescription" label="设备描述" align="center"></el-table-column>
      <el-table-column prop="deviceModel" label="设备型号" align="center"></el-table-column>
      <el-table-column prop="deviceManufacturer" label="设备厂商" align="center"></el-table-column>
      <el-table-column prop="typeCreateTime" label="录入时间" align="center"></el-table-column>
      <el-table-column prop="deviceCreateUser" label="录入人" align="center"></el-table-column>
      <el-table-column label="操作" align="center">
        <template slot-scope="scope">
          <div style="text-align: center">
            <el-button type="primary" @click="handleEdit(scope.row)"
              >编辑</el-button
            >
            <el-button type="danger" @click="handleDelete(scope.row)"
              >删除</el-button
            >
          </div>
        </template>
      </el-table-column>
    </el-table>

    <!-- 分页区域 -->
    <el-pagination
      @size-change="handleSizeChange"
      @current-change="handleCurrentChange"
      :current-page="currentPage"
      :page-sizes="[10, 20, 30, 40]"
      :page-size="pageSize"
      layout="total, sizes, prev, pager, next, jumper"
      :total="total"
      style="margin-top: 20px; text-align: center"
    >
    </el-pagination>
    <!-- 弹窗区域 -->
    <el-dialog
      :title="operateTitle"
      :visible.sync="dialogFormVisible"
      @close="clearQuery"
      :close-on-click-modal="false"
    >
      <el-form :model="insertForm" :rules="insertFormRules" ref="dialogForm">
        <el-form-item label="设备名称">
          <el-input v-model="insertForm.deviceName" autocomplete="off"></el-input>
        </el-form-item>
        <el-form-item label="设备编码">
          <el-input v-model="insertForm.deviceCode" autocomplete="off"></el-input>
        </el-form-item>
        <el-form-item label="设备描述">
          <el-input
            v-model="insertForm.deviceDescription"
            autocomplete="off"
          ></el-input>
        </el-form-item>
        <el-form-item label="设备型号">
          <el-input v-model="insertForm.deviceModel" autocomplete="off"></el-input>
        </el-form-item>
        <el-form-item label="设备厂商">
          <el-input v-model="insertForm.deviceManufacturer" autocomplete="off"></el-input>
        </el-form-item>
        <el-form-item label="关联分类">
          <el-cascader
              placeholder="请选择分类名称"
              :options="categoryList"
              v-model="insertCategory"
              filterable>
            </el-cascader>
        </el-form-item>

      </el-form>
      <div slot="footer">
        <el-button @click="clearQuery" type="danger">取 消</el-button>
        <el-button type="primary" @click="submitForm">确 定</el-button>
      </div>
    </el-dialog>
  </div>
</template>

<script>
import request from "@/utils/request.js";
export default {
  data() {
    return {
      queryForm: {
        deviceName: "",
        deviceModel: "",
        beginTime: "",
        endTime: "",
        deviceCreateUser: "",
      },
      insertForm: {
        id: "",
        deviceName: "",
        deviceCode:'',
        deviceModel:'',
        deviceManufacturer:'',
        deviceDescription: "",
        deviceCreateUser: "测试用户",
      },
      insertFormRules: {
        deviceTypeName: [
          { required: true, message: "请输入活动名称", trigger: "blur" },
          { min: 1, max: 25, message: "长度在1-25个字符", trigger: "blur" },
        ],
      },
      searchParam: {}, //查询参数
      categoryList: [], //分类
      tableData: [],
      currentPage: 1,
      pageSize: 10,
      total: 50,
      operateTitle: "", //操作类型标题
      dialogFormVisible: false, //弹窗
      operationType: "", //操作类型
      selectedCategory:["",""],//查询时选中的分类名称
      insertCategory:[0,0]//记录新增和编辑时的分类
    };
  },
  methods: {
    handleQuery() {
      Object.assign(this.searchParam, this.queryForm);
      this.$set(this.searchParam,"parentId",this.selectedCategory[0])
      this.$set(this.searchParam,"childId",this.selectedCategory[1])
      this.currentPage = 1
      this.searchByCondition();
    },
    //条件查询
    searchByCondition() {
      request
        .post("deviceManage/searchByCondition", {
          queryParam: this.searchParam,
          pageNum: this.currentPage,
          pageSize: this.pageSize,
        })
        .then((res) => {
          if (res && res.code == 200) {
            this.tableData = res.data.data;
            this.total = res.data.total
            this.currentPage = res.data.pageNum
            this.pageSize = res.data.pageSize
          }
        });
      this.getAllType();
    },
    handleReset() {
      // 重置查询表单
      this.queryForm = {
        deviceName: "",
        deviceModel: "",
        beginTime: "",
        endTime: "",
        deviceCreateUser: "",
      };
      this.selectedCategory = ["",""]
      this.handleQuery();
    },
    //关闭弹窗并清空校验和参数
    clearQuery() {
      this.insertForm = {
        id: "",
        deviceName: "",
        deviceCode:'',
        deviceModel:'',
        deviceManufacturer:'',
        deviceDescription: "",
        deviceCreateUser: "测试用户",
      };
      this.insertCategory= [0,0]
      this.dialogFormVisible = false;
      this.$refs.dialogForm.clearValidate();
    },
    handleAdd() {
      this.operateTitle = " 设备新增";
      this.operationType = "add";
      this.insertForm ={
        id: "",
        deviceName: "",
        deviceCode:'',
        deviceModel:'',
        deviceManufacturer:'',
        deviceDescription: "",
        deviceCreateUser: "测试用户",
      }
      this.dialogFormVisible = true;
    },
    handleEdit(row) {
      this.operateTitle = row.deviceName + " 编辑";
      this.insertForm = {
        id: row.id,
        deviceName: row.deviceName,
        deviceCode:row.deviceCode,
        deviceModel:row.deviceModel,
        deviceManufacturer:row.deviceManufacturer,
        deviceDescription: row.deviceDescription,
      };
    this.insertCategory=[Number(row.parentId),Number(row.childId)]
      this.operationType = "edit";
      this.dialogFormVisible = true;
      this.$forceUpdate()
    },
    submitForm() {
      if (this.operationType === "add") {
        this.$set(this.insertForm,"parentId",this.insertCategory[0])
        this.$set(this.insertForm,"childId",this.insertCategory[1])
        request.post("deviceManage/add", this.insertForm).then((res) => {
          if (res && res.code == 200) {
            this.$message.success("类型新增成功！");
            this.clearQuery();
            this.handleReset();
          } 
        });
      } else {
        this.$set(this.insertForm,"parentId",this.insertCategory[0])
        this.$set(this.insertForm,"childId",this.insertCategory[1])
        request
          .post("deviceManage/updateDeviceData", this.insertForm)
          .then((res) => {
            if (res && res.code == 200) {
              this.$message.success("修改成功！");
              this.clearQuery();
              this.handleReset();
            }
          });
      }
    },
    handleDelete(row) {
      this.$confirm(
        "此操作将删除分类：" +row.deviceName + ", 是否继续?",
        "提示",
        {
          confirmButtonText: "确定",
          cancelButtonText: "取消",
          type: "warning",
        }
      )
        .then(() => {
          request
            .post("deviceManage/deleteDeviceData", {
              id: row.id,
            })
            .then((res) => {
              if (res && res.code == 200) {
                this.$message.success("设备"+row.deviceName + "删除成功！");
                this.clearQuery();
                this.handleReset();
              }
            });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },
    handleSizeChange(val) {
      // 每页条数改变时的回调
      this.pageSize = val;
      this.searchByCondition()
    },
    handleCurrentChange(val) {
      // 当前页码改变时的回调
      this.currentPage = val;
     this.searchByCondition()
    },
    getAllType() {
      request.get("deviceType/getAllType").then((res) => {
        if (res && res.code == 200) {
          this.categoryList = res.data;
        }
      });
    },
    //根据id获取分类名字
    getCategoryName(parentId,child){
       const parentCategory =this.categoryList.filter(e => e.value ==parentId)[0]
       const childCategory = parentCategory.children.filter(e=> e.value ==child)[0]
       return parentCategory.label+"/"+childCategory.label
    },
  },
  created() {
    this.searchByCondition();
    this.getAllType();
  },
};
</script>

<style scoped>
.equipment-type-container {
  padding: 20px;
}
.query-form {
  margin-bottom: 20px;
}
</style>
